/**
 * VSIX freshness.
 *
 * A GUI gate that installs a stale VSIX verifies the wrong code: the reports
 * it writes then describe an artifact the source tree no longer matches. This
 * module answers one question — "does the packaged artifact still reflect the
 * sources it is built from?" — by comparing the artifact's timestamp against
 * the newest packaged *source* file.
 *
 * Only sources count. Build outputs (`dist`, `out`, `build`) and dependency
 * trees are regenerated by the prepublish step, so their timestamps would
 * report a stale artifact for a tree whose sources did not change.
 */
import fs from "node:fs";
import path from "node:path";

/** Directories whose contents never ship as packaged sources. */
const IGNORED_DIRECTORIES = new Set([
  ".git",
  ".mypy_cache",
  ".pytest_cache",
  ".venv",
  ".vscode-test",
  "__pycache__",
  "build",
  "coverage",
  "dist",
  "node_modules",
  "out",
  "venv",
]);

/** File suffixes that never ship as packaged sources. */
const IGNORED_SUFFIXES = [".log", ".pyc", ".pyo", ".vsix"];

/** Source directories that the prepublish step packages into the VSIX. */
const SOURCE_DIRECTORIES = [
  ["extension", "src"],
  ["extension", "scripts"],
  ["extension", "webview", "src"],
  ["shared", "src"],
  ["server", "app"],
  ["browser-extension"],
  ["remote-extension", "src"],
];

/** Single source files that the prepublish step packages into the VSIX. */
const SOURCE_FILES = [
  ["extension", "package.json"],
  ["extension", "webview", "package.json"],
  ["extension", "webview", "index.html"],
  ["extension", "webview", "vite.config.ts"],
  ["extension", "webview", "tsconfig.json"],
];

function isIgnoredDirectory(name) {
  return IGNORED_DIRECTORIES.has(name);
}

function isIgnoredFile(name) {
  return IGNORED_SUFFIXES.some((suffix) => name.toLowerCase().endsWith(suffix));
}

function collectFiles(root, collected) {
  let entries;
  try {
    entries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return collected;
  }
  for (const entry of entries) {
    const absolute = path.join(root, entry.name);
    if (entry.isDirectory()) {
      if (isIgnoredDirectory(entry.name)) {
        continue;
      }
      collectFiles(absolute, collected);
      continue;
    }
    if (!entry.isFile() || isIgnoredFile(entry.name)) {
      continue;
    }
    try {
      collected.push({ file: absolute, mtimeMs: fs.statSync(absolute).mtimeMs });
    } catch {
      // A file that vanished mid-scan cannot make the artifact stale.
    }
  }
  return collected;
}

/**
 * Every packaged source file with its last-modified time.
 *
 * @param {{ repoRoot: string }} options
 * @returns {{ file: string, mtimeMs: number }[]}
 */
export function collectVsixSourceInputs({ repoRoot }) {
  const collected = [];
  for (const segments of SOURCE_DIRECTORIES) {
    collectFiles(path.join(repoRoot, ...segments), collected);
  }
  for (const segments of SOURCE_FILES) {
    const absolute = path.join(repoRoot, ...segments);
    try {
      const stats = fs.statSync(absolute);
      if (stats.isFile()) {
        collected.push({ file: absolute, mtimeMs: stats.mtimeMs });
      }
    } catch {
      // A missing optional input is not a freshness signal.
    }
  }
  return collected;
}

/**
 * Compare a packaged artifact against the sources it is built from.
 *
 * @param {{ repoRoot: string, vsixPath: string }} options
 * @returns {{
 *   exists: boolean,
 *   stale: boolean,
 *   vsixPath: string,
 *   vsixMtimeMs: number | null,
 *   newestInput: { file: string, mtimeMs: number } | null,
 *   staleInputs: { file: string, mtimeMs: number }[],
 *   inputCount: number,
 * }}
 */
export function resolveVsixFreshness({ repoRoot, vsixPath }) {
  const inputs = collectVsixSourceInputs({ repoRoot });
  let vsixMtimeMs = null;
  try {
    vsixMtimeMs = fs.statSync(vsixPath).mtimeMs;
  } catch {
    vsixMtimeMs = null;
  }
  const sorted = [...inputs].sort((left, right) => right.mtimeMs - left.mtimeMs);
  const newestInput = sorted[0] ?? null;
  const staleInputs = vsixMtimeMs === null
    ? sorted
    : sorted.filter((input) => input.mtimeMs > vsixMtimeMs);
  return {
    exists: vsixMtimeMs !== null,
    stale: vsixMtimeMs === null || staleInputs.length > 0,
    vsixPath,
    vsixMtimeMs,
    newestInput,
    staleInputs,
    inputCount: inputs.length,
  };
}

/**
 * A short, actionable report of why a packaged artifact cannot be trusted.
 *
 * @param {{ repoRoot: string, vsixPath: string }} options
 * @returns {string}
 */
export function describeVsixFreshness({ repoRoot, vsixPath }) {
  const freshness = resolveVsixFreshness({ repoRoot, vsixPath });
  if (!freshness.exists) {
    return `Packaged VSIX is missing: ${vsixPath}. Run npm run package:vsix first.`;
  }
  if (!freshness.stale) {
    return `Packaged VSIX is current (${freshness.inputCount} packaged sources checked).`;
  }
  const newest = freshness.newestInput;
  const newestName = newest ? path.relative(repoRoot, newest.file) : "unknown";
  const lines = [
    `Packaged VSIX is older than the sources it packages: ${vsixPath}`,
    `- newest packaged source: ${newestName}`,
    `- stale packaged sources: ${freshness.staleInputs.length} of ${freshness.inputCount}`,
    "Run npm run package:vsix before the GUI gate so it verifies the current code.",
  ];
  return lines.join("\n");
}
